using System.Net;
using System.Globalization;
using System.Text;
using PropFlow.Modules.Billing.Domain.Invoices;
using PropFlow.Modules.Payments.Contracts;
namespace PropFlow.Modules.Billing.Infrastructure.Finance;
public static class FinanceDocuments
{
    public static string Encode(string? text) => WebUtility.HtmlEncode(text ?? "");
    public static string Money(decimal amount) => amount.ToString("N0", CultureInfo.GetCultureInfo("vi-VN")) + " đ";
    public static Guid EventId(string key) => new(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(key)).AsSpan(0, 16));
    public static string Invoice(Invoice invoice, InvoiceRecipient recipient, decimal paid)
    {
        var visible = recipient.Capacity == "OWNER" ? invoice.Items.Where(x => x.FeeCodeSnapshot != RentalPricing.FeeCode).ToArray() : invoice.Items.ToArray();
        var lines = string.Join("", visible.Select(x => $"<tr><td>{Encode(x.FeeNameSnapshot)}<br><small>{Encode(x.Description)}</small></td><td>{x.Quantity:N2} {Encode(x.UnitName)}</td><td>{Money(x.UnitRate)}{(x.AmountDivisor > 1 ? $" / {x.AmountDivisor} ngày" : "")}</td><td>{Money(x.LineAmount)}</td></tr>"));
        var rental = visible.Where(x => x.FeeCodeSnapshot == RentalPricing.FeeCode).Sum(x => x.LineAmount);
        var service = visible.Where(x => x.FeeCodeSnapshot != RentalPricing.FeeCode).Sum(x => x.LineAmount);
        var hasRental = visible.Any(x => x.FeeCodeSnapshot == RentalPricing.FeeCode);
        var breakdown = hasRental ? $"<p>Phí dịch vụ: {Money(service)}<br>Tiền thuê: {Money(rental)}</p>" : "";
        var total = service + rental;
        return Wrap(invoice.Type == InvoiceType.MONTHLY_RENTAL ? "HÓA ĐƠN TIỀN THUÊ THÁNG" : "HÓA ĐƠN PHÍ DỊCH VỤ", recipient, $"<p>Số hóa đơn: <b>{Encode(invoice.InvoiceNumber)}</b> · Ngày: {invoice.IssueDate:dd/MM/yyyy}</p><p>Kỳ phí: {invoice.BillingPeriodStart:MM/yyyy} · Hạn thanh toán: <b>{invoice.DueDate:dd/MM/yyyy}</b></p><table><thead><tr><th>Khoản phí</th><th>Số lượng</th><th>Đơn giá (VND)</th><th>Thành tiền</th></tr></thead><tbody>{lines}</tbody></table>{breakdown}<p class='total'>Tổng cộng: {Money(total)}</p><p>Đã xác nhận: {Money(paid)} · Còn phải trả: <b>{Money(Math.Max(0, total - paid))}</b></p>");
    }
    public static string Receipt(Invoice invoice, InvoiceRecipient recipient, PaymentNoticeSnapshot payment, decimal paid) =>
        $"<!doctype html><html lang='vi'><head><meta charset='utf-8'><title>PHIẾU XÁC NHẬN THANH TOÁN</title><style>body{{font-family:'Times New Roman',serif;font-size:13px;color:#000;margin:8px 24px;line-height:1.35}}h1{{font-size:13px;text-align:center;margin:0 0 4px;font-weight:bold}}p{{margin:0 0 3px}}ol{{margin:0 0 3px;padding-left:48px}}ul{{list-style:none;margin:0;padding-left:14px}}.ref{{float:right;margin-right:20%}}.amount,.notice{{color:red}}.notice{{font-weight:bold;font-style:italic}}@media print{{body{{margin:8px}}}}</style></head><body><h1>PHIẾU XÁC NHẬN THANH TOÁN HÓA ĐƠN KỲ {invoice.BillingPeriodStart:MM/yyyy}</h1><p>Thân gửi cư dân: {Encode(recipient.FullName)}<span class='ref'><b>Mã phiếu:</b> {Encode(payment.Number)}</span></p><p>Ban Kế toán xác nhận đã ghi nhận khoản thanh toán cho căn hộ <b>{Encode(recipient.UnitNumber)}</b>.</p><p>Thông tin giao dịch đã xác nhận, chi tiết như sau:</p><ol><li><b>Thông tin thanh toán:</b><ul><li>- Mã giao dịch: {Encode(payment.Number)}</li><li>- Thời điểm xác nhận: {payment.ConfirmedAt?.ToOffset(TimeSpan.FromHours(7)):dd/MM/yyyy HH:mm}</li><li>- Phương thức: {(payment.Method == "CASH" ? "Tiền mặt" : "Chuyển khoản")}</li></ul></li><li><b>Số tiền đã nhận:</b><ul><li>- Giao dịch này: <b class='amount'>{Money(payment.Amount)}</b></li><li>- Tổng đã xác nhận của hóa đơn: {Money(paid)}</li><li>- Còn phải thanh toán: {Money(Math.Max(0,invoice.TotalAmount-paid))}</li></ul></li><li><b>Hóa đơn liên quan:</b><ul><li>- Mã hóa đơn: {Encode(invoice.InvoiceNumber)}</li><li>- Kỳ hóa đơn: {invoice.BillingPeriodStart:MM/yyyy}</li><li>- Tổng giá trị hóa đơn: {Money(invoice.TotalAmount)}</li></ul></li><li><b>Đối chiếu:</b><ul><li>- Khoản tiền trên đã được kế toán xác nhận trong hệ thống.</li><li>- Vui lòng giữ phiếu này để đối chiếu cùng hóa đơn và giao dịch thanh toán.</li></ul></li></ol><p class='notice'>Lưu ý: Phiếu chỉ xác nhận số tiền của giao dịch này. Dư nợ còn lại được thể hiện ở mục 2.</p><p>Trân trọng thông báo,</p><p>Ban Kế toán PropFlow</p></body></html>";
    public static string Wrap(string title, InvoiceRecipient r, string body) => $"<!doctype html><html lang='vi'><head><meta charset='utf-8'><title>{Encode(title)}</title><style>body{{font-family:Arial,sans-serif;color:#24334b;margin:32px auto;max-width:780px;padding:20px}}header{{display:flex;justify-content:space-between;border-bottom:3px solid #7764ef;padding-bottom:16px}}h1{{color:#7764ef;font-size:27px}}table{{border-collapse:collapse;width:100%;margin-top:24px}}td,th{{border:1px solid #ded9f8;padding:12px;text-align:left}}th{{background:#f1edff}}.total{{text-align:right;font-size:22px;font-weight:bold}}@media print{{body{{margin:0}}}}</style></head><body><header><h1>{Encode(title)}</h1><p><b>PropFlow</b><br>Ban quản lý chung cư</p></header><p><b>THÔNG TIN CƯ DÂN</b><br>Họ tên: {Encode(r.FullName)}<br>Căn hộ: {Encode(r.UnitNumber)} · Diện tích: {r.AreaM2:N2} m²</p>{body}</body></html>";
}
